#include "raylib.h"
#include "raymath.h"
#include <algorithm>
#include <cmath>
#include <vector>
struct Wall{Vector3 p,s;}; struct Fuse{Vector3 p;bool got=false;};
static float D(Vector3 a,Vector3 b){return Vector3Distance({a.x,0,a.z},{b.x,0,b.z});}
static bool Block(Vector3 p,const Wall&w,float r){return p.x>w.p.x-w.s.x/2-r&&p.x<w.p.x+w.s.x/2+r&&p.z>w.p.z-w.s.z/2-r&&p.z<w.p.z+w.s.z/2+r;}
static void Move(Vector3& p,Vector3 v,float r,const std::vector<Wall>& ws){Vector3 q=p;q.x+=v.x;for(auto&w:ws)if(Block(q,w,r)){q.x=p.x;break;}p=q;q=p;q.z+=v.z;for(auto&w:ws)if(Block(q,w,r)){q.z=p.z;break;}p=q;}
static Texture2D Tex(Color a,Color b,int seed){Image im=GenImageColor(64,64,a);Color*px=LoadImageColors(im);unsigned s=seed*2654435761u+17;for(int y=0;y<64;y++)for(int x=0;x<64;x++){s^=s<<13;s^=s>>17;s^=s<<5;if(((x/7+y/9+seed)%3)==0||(s&255)>225)px[y*64+x]=b;}for(int i=0;i<4096;i++)im.data[i]=px[i];Texture2D t=LoadTextureFromImage(im);UnloadImageColors(px);UnloadImage(im);return t;}
static Sound Tone(float sec,float hz,float vol){int n=(int)(sec*22050);short*d=(short*)MemAlloc(n*sizeof(short));for(int i=0;i<n;i++){float t=i/22050.f,e=1.f-i/(float)n;d[i]=(short)(std::sin(2*PI*hz*t)*e*vol*32767);}Wave w={(unsigned)n,22050,16,1,d};Sound s=LoadSoundFromWave(w);UnloadWave(w);return s;}
static void Spatial(Sound s,Vector3 src,Vector3 listener,Vector3 right,float maxDist=14){float d=D(src,listener);float v=Clamp(1-d/maxDist,0,1);Vector3 dir={src.x-listener.x,0,src.z-listener.z};float pan=Vector3Length(dir)>0?Vector3Dot(Vector3Normalize(dir),right):0;SetSoundVolume(s,v*.45f);SetSoundPan(s,.5f+pan*.35f);}
int main(){SetConfigFlags(FLAG_MSAA_4X_HINT);InitWindow(1280,720,"Night House | C++ / CMake");InitAudioDevice();SetTargetFPS(60);DisableCursor();
Texture2D wall=Tex({76,70,62,255},{113,96,76,255},3),wood=Tex({54,34,24,255},{91,59,38,255},8),metal=Tex({52,55,55,255},{115,116,106,255},13),cloth=Tex({65,65,66,255},{105,100,92,255},21);
Sound pickup=Tone(.18f,740,.35f),door=Tone(.45f,90,.45f),heartbeat=Tone(.16f,55,.5f),attack=Tone(.6f,38,.8f),creak=Tone(.8f,145,.25f);
std::vector<Wall>w={{{-9.6f,1.5f,7},{.7f,3,18}},{{9.6f,1.5f,7},{.7f,3,18}},{{0,1.5f,-2},{20,3,.7f}},{{0,1.5f,16},{20,3,.7f}},{{-6,1.5f,5},{7,3,.7f}},{{5.5f,1.5f,5},{8,3,.7f}},{{-7,1.5f,10},{5,3,.7f}},{{5.5f,1.5f,11},{8,3,.7f}},{{-4,1.5f,1.8f},{.7f,3,4}},{{4,1.5f,1.8f},{.7f,3,4}},{{0,1.5f,8},{.7f,3,6}}};
std::vector<Fuse>fs={{{-7.5f,.9f,2.8f}},{{6.8f,.9f,7.8f}},{{2.8f,.9f,14}}};Camera3D cam{};cam.position={0,1.65f,13.5f};cam.up={0,1,0};cam.fovy=70;cam.projection=CAMERA_PERSPECTIVE;float yaw=PI,pitch=0,stam=1;Vector3 granny={0,1,12},goal=granny;int got=0;bool hide=false,dead=false,won=false,doorOpen=false;float msg=4;
auto reset=[&](){cam.position={0,1.65f,13.5f};yaw=PI;pitch=0;granny={0,1,12};goal=granny;got=0;stam=1;hide=false;dead=won=doorOpen=false;for(auto&f:fs)f.got=false;};
while(!WindowShouldClose()){float dt=std::min(GetFrameTime(),.05f);Vector3 fwd={std::sin(yaw),0,std::cos(yaw)},right={std::cos(yaw),0,-std::sin(yaw)};
if(dead||won){BeginDrawing();ClearBackground(dead?Color{20,3,5,255}:Color{7,30,12,255});DrawText(dead?"SHE FOUND YOU":"YOU ESCAPED",390,260,60,RAYWHITE);DrawText(dead?"The house was not empty.":"The front door is finally open.",400,335,22,Color{190,190,190,255});DrawText("ENTER: restart",520,410,20,RAYWHITE);EndDrawing();if(IsKeyPressed(KEY_ENTER))reset();continue;}
Vector2 md=GetMouseDelta();yaw+=md.x*.0025f;pitch=Clamp(pitch-md.y*.0022f,-1.35f,1.35f);fwd={std::sin(yaw),0,std::cos(yaw)};right={std::cos(yaw),0,-std::sin(yaw)};cam.target=Vector3Add(cam.position,{std::sin(yaw)*std::cos(pitch),std::sin(pitch),std::cos(yaw)*std::cos(pitch)});
bool sprint=IsKeyDown(KEY_LEFT_SHIFT)&&stam>.03f&&!hide;float sp=sprint?4.7f:2.6f;if(sprint)stam=std::max(0.f,stam-dt*.32f);else stam=std::min(1.f,stam+dt*.2f);Vector3 mv{};if(IsKeyDown(KEY_W))mv=Vector3Add(mv,fwd);if(IsKeyDown(KEY_S))mv=Vector3Subtract(mv,fwd);if(IsKeyDown(KEY_D))mv=Vector3Add(mv,right);if(IsKeyDown(KEY_A))mv=Vector3Subtract(mv,right);if(Vector3Length(mv)>0)mv=Vector3Scale(Vector3Normalize(mv),sp*dt);if(IsKeyPressed(KEY_E))hide=!hide;if(!hide)Move(cam.position,mv,.34f,w);
for(auto&x:fs)if(!x.got&&D(cam.position,x.p)<1.15f){x.got=true;got++;msg=2.5f;PlaySound(pickup);}if(got==3&&D(cam.position,{0,1,-1.3f})<1.7f&&IsKeyPressed(KEY_E)){doorOpen=true;PlaySound(door);won=true;}
float gd=D(granny,cam.position);bool alert=gd<9||sprint&&gd<15;if(alert&&!hide)goal=cam.position;else if(D(granny,goal)<.8f||GetRandomValue(0,120)==0)goal={(float)GetRandomValue(-7,7),1,(float)GetRandomValue(2,14)};Vector3 av=Vector3Subtract(goal,granny);av.y=0;if(Vector3Length(av)>.1f){av=Vector3Scale(Vector3Normalize(av),(alert?2.65f:1.f)*dt);Move(granny,av,.45f,w);}if(gd<1&&!hide){dead=true;Spatial(attack,granny,cam.position,right);PlaySound(attack);}if(gd<6&&!hide&&GetRandomValue(0,45)==0){Spatial(heartbeat,granny,cam.position,right);PlaySound(heartbeat);}if(GetRandomValue(0,240)==0){Spatial(creak,{(float)GetRandomValue(-8,8),1,(float)GetRandomValue(1,15)},cam.position,right);PlaySound(creak);}
BeginDrawing();ClearBackground({7,7,9,255});BeginMode3D(cam);DrawPlane({0,0,7},{20,22},{47,43,38,255});DrawPlane({0,3,7},{20,22},{30,29,27,255});for(auto&x:w){DrawCubeTexture(wall,x.p,x.s.x,x.s.y,x.s.z,WHITE);DrawCubeWires(x.p,x.s.x,x.s.y,x.s.z,{20,18,17,255});}DrawCubeTexture(wood,{-7.2f,.75f,2.5f},3,.9f,1.2f,WHITE);DrawCubeTexture(wood,{7.1f,1,3.1f},2,2,.7f,WHITE);DrawCubeTexture(cloth,{-7.2f,1,12.5f},2.2f,2,.7f,WHITE);DrawCubeTexture(metal,{6.8f,.7f,12.7f},1.3f,1.4f,1.3f,WHITE);if(!doorOpen){DrawCubeTexture(wood,{0,1.5f,-1.25f},2.2f,3,.25f,WHITE);DrawSphere({.55f,1.5f,-1.05f},.09f,{180,150,70,255});}for(auto&x:fs)if(!x.got){float p=.11f+.025f*std::sin(GetTime()*5);DrawCylinder(x.p,.16f,.42f,12,{210,205,175,255});DrawSphere({x.p.x,x.p.y+.23f,x.p.z},p,{240,230,150,255});}
float y=granny.y;DrawCylinder({granny.x,y+.78f,granny.z},.43f,.95f,12,{70,63,60,255});DrawSphere({granny.x,y+1.48f,granny.z},.4f,{155,132,112,255});DrawSphere({granny.x-.14f,y+1.53f,granny.z-.34f},.055f,{18,8,7,255});DrawSphere({granny.x+.14f,y+1.53f,granny.z-.34f},.055f,{18,8,7,255});DrawCylinder({granny.x,y+.18f,granny.z},.52f,.16f,12,{44,37,36,255});EndMode3D();DrawRectangle(0,0,1280,78,{0,0,0,150});DrawText("NIGHT HOUSE",25,16,26,RAYWHITE);DrawText(TextFormat("FUSES %d / 3",got),28,48,17,{200,195,180,255});DrawText("WASD move   SHIFT sprint   E hide/interact",370,23,17,{175,175,175,255});DrawRectangle(1010,23,210,12,{30,30,30,230});DrawRectangle(1010,23,(int)(210*stam),12,RAYWHITE);if(got==3)DrawText("The front door can be opened",430,650,22,{235,220,170,255});if(hide)DrawText("HIDING",580,690,18,{190,190,190,255});if(msg>0){DrawText("Find the three fuses. Do not let her hear you.",355,105,19,{210,200,180,255});msg-=dt;}EndDrawing();}
UnloadTexture(wall);UnloadTexture(wood);UnloadTexture(metal);UnloadTexture(cloth);UnloadSound(pickup);UnloadSound(door);UnloadSound(heartbeat);UnloadSound(attack);UnloadSound(creak);CloseAudioDevice();CloseWindow();return 0;}
